// SwappableDB is a wrapper around DB that allows the underlying database to be swapped out
// in a thread-safe manner.
type SwappableDB struct {
	db            *DB
	drv           *Driver
	checkpointMgr *CheckpointManager
	dbMu          sync.RWMutex
